import sys

def can_erase(s):
    count = {'A': 0, 'B': 0, 'C': 0}
    for char in s:
        count[char] += 1
    if count['B'] < min(count['A'], count['C']):
        return "NO"
    if (count['A'] + count['C']) % 2 != 0:
        return "NO"
    return "YES"

def main():
    import sys
    input = sys.stdin.read().split()
    t = int(input[0])
    results = []
    for i in range(1, t + 1):
        s = input[i]
        results.append(can_erase(s))
    print("\n".join(results))

if __name__ == "__main__":
    main()
